/* Complete DSA roadmap lessons: every roadmap topic has a real learning page. */
window.PYDSA_DSA_LESSONS = [
  {
    id:'programming-logic-loops', level:0, title:'Loops & Conditions', difficulty:'easy', summary:'Build the control-flow habits that every DSA solution depends on.',
    what:'Conditions choose a path; loops repeat a block of work. Together they let you describe most basic algorithms.',
    why:'Before learning data structures, you need to be comfortable turning a problem into repeated checks and updates.',
    simple:'Think of a traffic light. The condition decides what happens now, while a loop keeps checking the road until the journey is finished.',
    tech:'A conditional branches execution based on a Boolean expression. An iteration construct repeatedly executes a block while its loop condition or iterable produces work.',
    steps:['Read the input and identify the state you need to track.','Write the condition that decides whether the current item matters.','Choose a loop that visits every required item.','Update your state inside the loop and stop when the work is complete.'],
    code:'numbers = [4, 7, 2, 9, 6]\n\ntotal = 0\nfor number in numbers:\n    if number % 2 == 0:\n        total += number\n\nprint(total)',
    output:'12',
    lines:[['for number in numbers:', 'Visits each value once.'],['if number % 2 == 0:', 'Checks whether the current value is even.'],['total += number', 'Adds matching values to the running total.']],
    mistakes:['Changing the loop variable when you only meant to update an accumulator.','Using a loop when a direct operation already solves the problem.'],
    use:'Use loops when work depends on every item, and conditions when the next action depends on the current state.',
    qa:[['What is the difference between if and while?', 'if makes one conditional decision; while can repeat a block while its condition remains true.'],['What is the usual complexity of one pass through n items?', 'O(n), because each item is processed once.']],
    practice:'Count how many values in a list are greater than a target.', hint:'Keep a counter and increment it only when the condition is true.', solution:'count = 0\nfor x in [3, 8, 2, 9]:\n    if x > 5:\n        count += 1\nprint(count)', related:['arrays-strings-01']
  },
  {
    id:'programming-logic-functions', level:0, title:'Functions', difficulty:'easy', summary:'Turn repeated logic into named, testable building blocks.',
    what:'A function packages a piece of logic behind a name, accepts inputs through parameters, and can return a result.', why:'Algorithms become easier to reason about when each piece has one clear job.', simple:'A function is like a small machine: give it inputs, let it do one job, and collect the result.', tech:'A Python function creates a callable object with a local scope. Parameters receive arguments and return transfers a value to the caller.', steps:['Name the job clearly.','Choose the inputs the job actually needs.','Compute the result without relying on unnecessary global state.','Return the result and test the function separately.'], code:'def find_max(numbers):\n    best = numbers[0]\n    for x in numbers[1:]:\n        if x > best:\n            best = x\n    return best\n\nprint(find_max([4, 9, 2, 7]))', output:'9', lines:[['def find_max(numbers):','Defines a reusable function.'],['best = numbers[0]','Starts with the first value as the current maximum.'],['return best','Sends the answer back to the caller.']], mistakes:['Forgetting a return statement.','Making a function depend on unrelated global variables.'], use:'Use functions whenever a logical operation can be named and tested independently.', qa:[['Why are functions useful in DSA?', 'They isolate algorithmic steps, make recursion possible, and make testing easier.']], practice:'Write a function that returns the sum of all values in a list.', hint:'Start at zero and accumulate in a loop.', solution:'def total(values):\n    answer = 0\n    for x in values:\n        answer += x\n    return answer', related:['recursion-math-01']
  },
  {
    id:'programming-logic-patterns', level:0, title:'Pattern Printing', difficulty:'easy', summary:'Use nested loops to understand rows, columns, and repeated structure.', what:'Pattern problems print characters or numbers according to row and column rules.', why:'They force you to reason about nested loops, boundaries, spacing, and changing work per row.', simple:'Imagine drawing a shape one row at a time. The outer loop chooses the row; the inner loop decides what appears in that row.', tech:'Nested iteration gives an O(r*c) structure for r rows and c columns unless each row uses a constant-time string operation.', steps:['Decide how many rows exist.','For each row, calculate how many symbols or spaces it needs.','Print the row and move to the next line.'], code:'rows = 4\nfor i in range(1, rows + 1):\n    print("*" * i)', output:'*\n**\n***\n****', lines:[['range(1, rows + 1)','Generates row numbers 1 through rows.'],['"*" * i','Creates exactly i stars for the current row.']], mistakes:['Mixing up row count and column count.','Forgetting to move to a new line after each row.'], use:'Use patterns to practise loop logic before moving to nested-loop algorithms.', qa:[['What does the outer loop usually represent?', 'The current row or major unit of work.']], practice:'Print a right-aligned triangle of stars.', hint:'Print spaces before the stars.', solution:'rows = 4\nfor i in range(1, rows + 1):\n    print(" " * (rows - i) + "*" * i)', related:['patterns-01','patterns-03']
  },

  {
    id:'complexity-big-o', level:1, title:'Complexity & Big O', difficulty:'easy', summary:'Measure how an algorithm grows as the input gets larger.', what:'Big O describes an upper-bound growth rate such as O(1), O(log n), O(n), or O(n²).', why:'Two correct solutions can behave very differently on large inputs. Complexity helps you choose the scalable one.', simple:'If a list doubles, ask: does your work stay the same, double, or become four times larger?', tech:'Time complexity models the number of basic operations as a function of input size; space complexity models additional memory usage.', steps:['Identify the input size n.','Count how many times the main work can execute.','Drop constants and lower-order terms for Big O.','Also check extra memory, not only time.'], code:'def has_duplicate(values):\n    seen = set()\n    for x in values:\n        if x in seen:\n            return True\n        seen.add(x)\n    return False', output:'No printed output; returns True/False.', lines:[['seen = set()','Stores values already encountered.'],['if x in seen:','Average O(1) membership check.'],['seen.add(x)','Records the current value.']], mistakes:['Calling every nested loop O(n²) without checking whether the inner range is actually constant.','Ignoring space complexity.','Confusing worst-case O(log n) binary search with linear search O(n).'], use:'Use complexity analysis whenever you compare solutions or need to judge whether a solution will scale.', qa:[['What is binary search complexity?', 'O(log n) time on a sorted sequence and O(1) extra space for an iterative implementation.'],['What does O(1) mean?', 'The amount of work does not grow with input size.']], practice:'Classify a loop that visits every element once.', hint:'Ask how many iterations happen when n grows.', solution:'for x in values:\n    print(x)\n# O(n) time', related:['searching-sorting-01']
  },
  {
    id:'arrays', level:1, title:'Arrays', difficulty:'easy', summary:'Store values in indexed order and learn the operations that make arrays useful.', what:'In Python, lists provide dynamic array-like storage with indexed access.', why:'Arrays are the base structure behind many searching, sorting, prefix-sum, and two-pointer problems.', simple:'Think of numbered boxes placed next to each other. Indexing tells you which box to open.', tech:'Python lists provide amortized O(1) append and O(1) indexed access, while inserting or deleting near the front requires shifting elements and is O(n).', steps:['Choose the index or traversal you need.','Use direct indexing when the position is known.','Traverse when you need to inspect values.','Remember that middle insertion/deletion can shift many elements.'], code:'values = [10, 20, 30, 40]\nprint(values[2])\nvalues.append(50)\nprint(values)', output:'30\n[10, 20, 30, 40, 50]', lines:[['values[2]','Reads the third item in O(1) average time.'],['values.append(50)','Adds a value to the end in amortized O(1).']], mistakes:['Using an invalid index.','Assuming insert(0, x) is O(1).'], use:'Use arrays when you need ordered data, indexing, iteration, or compact storage.', qa:[['Why is list indexing O(1)?', 'The list stores references in an array-like contiguous table, so the index can be calculated directly.']], practice:'Find the largest value without using max().', hint:'Keep a best value while scanning.', solution:'best = values[0]\nfor x in values[1:]:\n    if x > best:\n        best = x', related:['arrays-strings-01','arrays-strings-2-01']
  },
  {
    id:'strings', level:1, title:'Strings', difficulty:'easy', summary:'Treat text as a sequence and learn the operations behind common string problems.', what:'A Python string is an immutable sequence of Unicode characters.', why:'Interview questions frequently turn strings into counting, searching, two-pointer, or sliding-window problems.', simple:'A string is a row of characters. You can inspect positions, but changing one character creates a new string.', tech:'Strings support indexed access and slicing; because they are immutable, operations that construct modified strings allocate new objects.', steps:['Decide whether order matters.','Count characters when frequency matters.','Use indexing or slicing for positional work.','Use a set or dictionary when you need membership or counts.'], code:'text = "banana"\ncounts = {}\nfor ch in text:\n    counts[ch] = counts.get(ch, 0) + 1\nprint(counts)', output:"{'b': 1, 'a': 3, 'n': 2}", lines:[['counts.get(ch, 0)','Reads the existing count or starts at zero.'],['counts[ch] = ...','Stores the updated frequency.']], mistakes:['Trying to assign text[0] = ...','Using repeated concatenation inside a large loop when a list + join is clearer.'], use:'Use strings for text and combine them with hashing, two pointers, or window techniques for interview problems.', qa:[['Are Python strings mutable?', 'No. A new string is created when you produce a modified version.']], practice:'Check whether two strings are anagrams.', hint:'Compare character frequency maps.', solution:'from collections import Counter\nanswer = Counter(a) == Counter(b)', related:['arrays-strings-2-02']
  },
  {
    id:'searching', level:1, title:'Searching', difficulty:'easy', summary:'Find a target efficiently by choosing the right search strategy.', what:'Searching means locating a value or deciding whether it exists.', why:'The search method can reduce work from O(n) to O(log n) when the data is sorted.', simple:'Linear search checks boxes one by one. Binary search keeps cutting the remaining range in half.', tech:'Linear search is O(n). Binary search requires sorted data and is O(log n) by halving the candidate interval each step.', steps:['Check whether the data is sorted.','If not, use a linear scan or prepare the data.','If sorted, compare the target with the middle value.','Discard the half that cannot contain the target.'], code:'def binary_search(values, target):\n    left, right = 0, len(values) - 1\n    while left <= right:\n        mid = (left + right) // 2\n        if values[mid] == target:\n            return mid\n        if values[mid] < target:\n            left = mid + 1\n        else:\n            right = mid - 1\n    return -1\n\nprint(binary_search([2, 4, 7, 9, 12], 9))', output:'3', lines:[['mid = (left + right) // 2','Chooses the middle candidate.'],['left = mid + 1','Discards the left half when the target is larger.'],['right = mid - 1','Discards the right half when the target is smaller.']], mistakes:['Using binary search on unsorted data.','Using the wrong boundary update and causing an infinite loop.'], use:'Use linear search for unsorted data or tiny inputs; use binary search when the search space is ordered and the monotonic condition is valid.', qa:[['Why is binary search O(log n)?', 'Each comparison removes roughly half of the remaining candidates.']], practice:'Return the first index of a target in a sorted list.', hint:'When you find the target, save it and keep searching left.', solution:'answer = -1\nleft, right = 0, len(values) - 1\nwhile left <= right:\n    mid = (left + right) // 2\n    if values[mid] >= target:\n        if values[mid] == target:\n            answer = mid\n        right = mid - 1\n    else:\n        left = mid + 1', related:['searching-sorting-01','searching-sorting-02']
  },
  {
    id:'sorting', level:1, title:'Sorting', difficulty:'medium', summary:'Rearrange data into order and understand the trade-offs between classic sorting algorithms.', what:'Sorting rearranges values according to an ordering rule.', why:'Sorted data enables binary search, two pointers, merging, and many greedy strategies.', simple:'Sorting is like putting books on a shelf by title so later searches become easier.', tech:'Comparison sorts repeatedly establish ordering relationships. Common complexities range from O(n²) for simple educational sorts to O(n log n) for merge sort and average-case quicksort.', steps:['Decide the required order.','Choose a sort based on constraints and stability needs.','After sorting, exploit the new order with another technique.'], code:'def insertion_sort(values):\n    for i in range(1, len(values)):\n        key = values[i]\n        j = i - 1\n        while j >= 0 and values[j] > key:\n            values[j + 1] = values[j]\n            j -= 1\n        values[j + 1] = key\n\nvalues = [5, 2, 4, 1]\ninsertion_sort(values)\nprint(values)', output:'[1, 2, 4, 5]', lines:[['key = values[i]','Stores the value being inserted.'],['values[j + 1] = values[j]','Shifts larger values one position right.'],['values[j + 1] = key','Places the key in its sorted position.']], mistakes:['Forgetting that Python sorted() is usually the practical choice.','Choosing O(n²) sorting for very large data without reason.'], use:'Use built-in sorting in real Python unless an interview asks you to implement a sorting algorithm or constraints require a specialized method.', qa:[['When is insertion sort useful?', 'For small or nearly sorted data, and for learning how insertion works.']], practice:'Implement selection sort.', hint:'For each position, find the smallest remaining value.', solution:'for i in range(len(values)):\n    best = i\n    for j in range(i + 1, len(values)):\n        if values[j] < values[best]:\n            best = j\n    values[i], values[best] = values[best], values[i]', related:['searching-sorting-03','searching-sorting-04']
  },
  {
    id:'hashing', level:1, title:'Hashing', difficulty:'medium', summary:'Use sets and dictionaries to turn repeated searches into fast lookups.', what:'Hashing maps keys to locations so membership and key-based lookup are usually O(1) on average.', why:'Hash maps are one of the most important tools for turning brute-force O(n²) solutions into O(n).', simple:'Instead of checking every drawer, use a label that tells you which drawer to open.', tech:'A hash table computes a hash for a key and stores it in a bucket. Collisions are handled internally; average lookup is O(1), with O(n) worst-case behavior.', steps:['Ask what value must be remembered.','Choose a key that identifies it.','Store the information in a set or dictionary.','Look it up instead of scanning the whole input.'], code:'values = [2, 7, 11, 15]\ntarget = 9\nseen = set()\nfor x in values:\n    if target - x in seen:\n        print("pair found")\n        break\n    seen.add(x)', output:'No pair found', lines:[['seen = set()','Stores previously visited values.'],['target - x in seen','Checks whether the matching partner already exists.']], mistakes:['Using a list for repeated membership checks.','Forgetting what information the key must uniquely identify.'], use:'Use hashing for membership, frequency counting, grouping, duplicate detection, and pair-sum style problems.', qa:[['Set vs dict?', 'A set stores unique values; a dictionary stores key-value pairs.']], practice:'Solve Two Sum using a dictionary.', hint:'Store each value with its index and look for target - x.', solution:'seen = {}\nfor i, x in enumerate(values):\n    need = target - x\n    if need in seen:\n        answer = [seen[need], i]\n        break\n    seen[x] = i', related:['arrays-strings-2-03']
  },

  {
    id:'linked-list', level:2, title:'Linked List', difficulty:'medium', summary:'Store nodes connected by references instead of contiguous indexes.', what:'A linked list consists of nodes where each node stores a value and a reference to another node.', why:'It teaches pointer/reference manipulation and supports efficient insertion when you already have the correct node.', simple:'Imagine a treasure hunt where every note tells you where the next note is.', tech:'A singly linked list stores a value and next reference per node. Traversal is O(n), while insertion after a known node is O(1).', steps:['Create a node containing data and a next reference.','Start from the head.','Follow next until you reach the desired position or None.','Update references carefully when inserting or deleting.'], code:'class Node:\n    def __init__(self, value):\n        self.value = value\n        self.next = None\n\nhead = Node(10)\nhead.next = Node(20)\nhead.next.next = Node(30)\n\ncur = head\nwhile cur:\n    print(cur.value)\n    cur = cur.next', output:'10\n20\n30', lines:[['self.next = None','Starts the node without a successor.'],['head.next = Node(20)','Connects the first node to the second.'],['cur = cur.next','Moves one node forward.']], mistakes:['Losing the next reference before saving it.','Forgetting to update head when inserting at the beginning.'], use:'Use linked lists when pointer manipulation is the learning goal or when frequent insertion/deletion is needed at known positions.', qa:[['Why is random access slow?', 'You must follow links from the head, so accessing position k is O(k).']], practice:'Reverse a singly linked list.', hint:'Keep previous, current, and next references.', solution:'prev = None\ncur = head\nwhile cur:\n    nxt = cur.next\n    cur.next = prev\n    prev = cur\n    cur = nxt\nhead = prev', related:['linked-list-01','linked-list-02','linked-list-07']
  },
  {
    id:'stack', level:2, title:'Stack', difficulty:'easy', summary:'Learn LIFO: the last item added is the first item removed.', what:'A stack supports push and pop at one end.', why:'Stacks model nested work, undo operations, parsing, recursion, and monotonic-stack problems.', simple:'A stack of plates: you take the top plate first.', tech:'A stack is an abstract data type with push, pop, and peek operations, typically O(1) with a dynamic array or linked list.', steps:['Push items onto the top.','Peek when you need the top without removing it.','Pop when the top item is complete.','Never remove from the middle if you want stack semantics.'], code:'stack = []\nstack.append("A")\nstack.append("B")\nprint(stack.pop())\nprint(stack[-1])', output:'B\nA', lines:[['append("B")','Pushes B onto the top.'],['pop()','Removes and returns the top item.'],['stack[-1]','Peeks at the top without removing it.']], mistakes:['Calling pop() on an empty stack.','Using the wrong end of a list and accidentally making operations O(n).'], use:'Use stacks for parentheses, undo, DFS, expression parsing, and monotonic-stack problems.', qa:[['What does LIFO mean?', 'Last In, First Out.']], practice:'Check whether brackets are balanced.', hint:'Push opening brackets and match each closing bracket with the top.', solution:'pairs = {")": "(", "]": "[", "}": "{"}\nstack = []\nfor ch in text:\n    if ch in "([{": stack.append(ch)\n    elif not stack or stack.pop() != pairs[ch]:\n        answer = False\n        break\nelse:\n    answer = not stack', related:['stack-queue-01']
  },
  {
    id:'queue', level:2, title:'Queue', difficulty:'easy', summary:'Learn FIFO: the first item added is the first item removed.', what:'A queue adds at the back and removes from the front.', why:'Queues model scheduling, breadth-first search, buffering, and waiting lines.', simple:'People standing in a line: the person who arrived first goes first.', tech:'A queue supports enqueue and dequeue. Python collections.deque provides O(1) append and popleft.', steps:['Add new work at the back.','Remove the oldest work from the front.','Use deque for efficient front removal.'], code:'from collections import deque\nq = deque(["A", "B"])\nq.append("C")\nprint(q.popleft())\nprint(q)', output:"A\ndeque(['B', 'C'])", lines:[['q.append("C")','Adds C to the back.'],['q.popleft()','Removes the oldest element from the front.']], mistakes:['Using list.pop(0), which is O(n).','Confusing FIFO with stack LIFO behavior.'], use:'Use queues for BFS, task scheduling, producer-consumer workflows, and level-order processing.', qa:[['Why use deque instead of list?', 'Removing from the left of a list shifts the remaining elements; deque supports O(1) popleft.']], practice:'Process a list of tasks in FIFO order.', hint:'Use collections.deque.', solution:'from collections import deque\nq = deque(tasks)\nwhile q:\n    task = q.popleft()\n    print(task)', related:['stack-queue-02']
  },
  {
    id:'deque', level:2, title:'Deque', difficulty:'medium', summary:'Use a double-ended queue when both ends matter.', what:'A deque supports insertion and removal at both the front and back.', why:'Some sliding-window and queue problems need access to both ends efficiently.', simple:'Think of a hallway with doors at both ends: people can enter or leave from either side.', tech:'collections.deque provides O(1) append, appendleft, pop, and popleft operations.', steps:['Choose which end represents the newest or oldest item.','Use append/appendleft to add.','Use pop/popleft to remove.','For indexed random access, use a list instead.'], code:'from collections import deque\nd = deque([2, 3])\nd.appendleft(1)\nd.append(4)\nprint(d)\nprint(d.popleft(), d.pop())', output:'deque([1, 2, 3, 4])\n1 4', lines:[['appendleft(1)','Adds to the front.'],['pop()','Removes from the back.']], mistakes:['Treating deque like a random-access array.','Using list operations when both-end operations dominate.'], use:'Use deque for queues, sliding windows, and two-ended processing.', qa:[['What is the key difference between queue and deque?', 'A queue normally exposes one insertion end and one removal end; a deque supports both ends.']], practice:'Keep only the last k values while scanning a stream.', hint:'Remove old values from the left and add new values to the right.', solution:'window = deque()\nfor x in values:\n    window.append(x)\n    if len(window) > k:\n        window.popleft()', related:['stack-queue-06']
  },

  {
    id:'two-pointers', level:3, title:'Two Pointers', difficulty:'medium', summary:'Move two indexes strategically instead of checking every pair.', what:'Two pointers maintain two positions in a sequence and move them according to the problem condition.', why:'It can reduce pairwise brute force from O(n²) to O(n) after sorting or when the input already has useful order.', simple:'Instead of comparing every person with everyone, place one finger at each end and move the fingers based on what you learn.', tech:'Two-pointer algorithms maintain indices with an invariant that eliminates impossible states as pointers advance.', steps:['Identify the order or invariant that makes pointer movement safe.','Place pointers at the useful starting positions.','Evaluate the current pair/window.','Move one or both pointers according to the invariant.'], code:'def has_pair(values, target):\n    left, right = 0, len(values) - 1\n    while left < right:\n        total = values[left] + values[right]\n        if total == target:\n            return True\n        if total < target:\n            left += 1\n        else:\n            right -= 1\n    return False', output:'Boolean result', lines:[['left, right = 0, len(values) - 1','Starts at both ends of a sorted list.'],['total = ...','Measures the current pair.'],['left += 1 / right -= 1','Moves toward a possible solution without revisiting eliminated pairs.']], mistakes:['Applying the technique without the required ordering/invariant.','Moving the wrong pointer.'], use:'Use two pointers for sorted pair sums, partitioning, palindrome checks, and many in-place array transformations.', qa:[['Why does moving a pointer not miss the answer?', 'The ordering invariant proves that all states skipped by that movement cannot satisfy the target.']], practice:'Check whether a string is a palindrome ignoring case.', hint:'Compare left and right characters and move inward.', solution:'left, right = 0, len(text) - 1\nwhile left < right:\n    if text[left].lower() != text[right].lower():\n        answer = False\n        break\n    left += 1\n    right -= 1', related:['arrays-strings-2-04']
  },
  {
    id:'sliding-window', level:3, title:'Sliding Window', difficulty:'medium', summary:'Maintain a changing contiguous range instead of recomputing every subarray.', what:'A sliding window keeps a left and right boundary and updates only what enters or leaves the range.', why:'It turns many O(n²) contiguous-subarray problems into O(n).', simple:'Imagine looking through a moving train window: when it moves right, one item leaves and another enters.', tech:'The technique maintains an invariant over a contiguous interval, expanding or shrinking boundaries while updating aggregate state.', steps:['Define what makes a window valid.','Expand the right side to include new data.','Shrink from the left whenever the window becomes invalid or too large.','Record the best valid window.'], code:'def longest_unique(text):\n    seen = set()\n    left = 0\n    best = 0\n    for right, ch in enumerate(text):\n        while ch in seen:\n            seen.remove(text[left])\n            left += 1\n        seen.add(ch)\n        best = max(best, right - left + 1)\n    return best\n\nprint(longest_unique("abcabcbb"))', output:'3', lines:[['while ch in seen','Shrinks the window until the invariant is restored.'],['best = max(...)','Records the largest valid window.']], mistakes:['Not removing outgoing state when moving left.','Using a fixed window when the problem needs a variable window.'], use:'Use for contiguous arrays/strings involving longest, shortest, count, sum, or frequency constraints.', qa:[['When is sliding window inappropriate?', 'When the problem is not about a contiguous range or when the state cannot be updated efficiently as the window moves.']], practice:'Find the maximum sum of any window of size k.', hint:'Add the new right value and subtract the outgoing left value.', solution:'window = sum(values[:k])\nbest = window\nfor right in range(k, len(values)):\n    window += values[right] - values[right-k]\n    best = max(best, window)', related:['arrays-strings-2-05']
  },
  {
    id:'prefix-sum', level:3, title:'Prefix Sum', difficulty:'medium', summary:'Precompute cumulative totals so range sums become constant-time queries.', what:'A prefix sum stores the total from the beginning up to each position.', why:'It replaces repeated range summation with O(1) queries after O(n) preprocessing.', simple:'Write down the running total at every position. Any range total can then be found by subtracting two checkpoints.', tech:'With prefix[i] representing the sum before index i, sum(l..r) = prefix[r+1] - prefix[l].', steps:['Create prefix[0] = 0.','Append each running total.','For a range [l, r], subtract the prefix before l from the prefix after r.'], code:'values = [2, 4, 1, 5, 3]\nprefix = [0]\nfor x in values:\n    prefix.append(prefix[-1] + x)\n\nl, r = 1, 3\nprint(prefix[r + 1] - prefix[l])', output:'10', lines:[['prefix.append(prefix[-1] + x)','Stores the running total.'],['prefix[r + 1] - prefix[l]','Subtracts everything before l from the total through r.']], mistakes:['Off-by-one errors in prefix indexes.','Forgetting that prefix arrays are often one element longer than the input.'], use:'Use prefix sums for many static range-sum queries and cumulative-balance problems.', qa:[['Why add a leading zero?', 'It makes a range beginning at index 0 use the same subtraction formula.']], practice:'Answer three range-sum queries efficiently.', hint:'Build prefix once, then answer each query with two accesses.', solution:'prefix = [0]\nfor x in values: prefix.append(prefix[-1] + x)\nanswers = [prefix[r+1] - prefix[l] for l, r in queries]', related:['arrays-strings-2-06']
  },
  {
    id:'binary-search-patterns', level:3, title:'Binary Search Patterns', difficulty:'medium', summary:'Go beyond searching a value: binary-search any monotonic answer space.', what:'Binary search can find the first/last valid position or the smallest value that satisfies a monotonic condition.', why:'Many interview problems hide a sorted answer space even when the input itself is not a sorted list.', simple:'If every answer below a boundary fails and every answer above it works, binary search can find the boundary.', tech:'The search space is valid when feasibility is monotonic: false values form one region and true values form another. Search for the transition point.', steps:['Define the candidate answer space.','Write a feasibility function.','Check the midpoint.','Move toward the first valid or last invalid boundary.'], code:'def first_true(lo, hi, ok):\n    while lo < hi:\n        mid = (lo + hi) // 2\n        if ok(mid):\n            hi = mid\n        else:\n            lo = mid + 1\n    return lo', output:'Returns the first value for which ok(value) is True.', lines:[['if ok(mid):','Checks whether the midpoint is already feasible.'],['hi = mid','Keeps mid because it may be the first valid answer.'],['lo = mid + 1','Rejects the entire lower half when mid is invalid.']], mistakes:['Using a non-monotonic feasibility function.','Losing the candidate boundary with hi = mid - 1 when searching for first true.'], use:'Use for lower/upper bounds, capacity/speed problems, and any monotonic decision problem.', qa:[['What makes answer-space binary search possible?', 'The feasibility predicate must change in one direction only across the search space.']], practice:'Find the minimum capacity needed to ship weights within D days.', hint:'Binary search capacity; simulate how many days each capacity requires.', solution:'lo, hi = max(weights), sum(weights)\nwhile lo < hi:\n    mid = (lo + hi) // 2\n    # simulate days needed for mid capacity\n    # move hi/lo based on feasibility', related:['searching-sorting-02']
  },
  {
    id:'recursion', level:3, title:'Recursion', difficulty:'medium', summary:'Solve a problem by reducing it to smaller versions of itself.', what:'A recursive function calls itself on a smaller subproblem until it reaches a base case.', why:'Trees, backtracking, divide-and-conquer, and many mathematical definitions naturally use recursion.', simple:'Ask a smaller version of the same question, and keep shrinking until the answer is obvious.', tech:'A recursive algorithm requires a base case and a recursive case that makes progress toward the base case.', steps:['Define the smallest input you can answer directly.','Express the current answer using a smaller input.','Ensure every call moves toward the base case.','Trace the call stack when debugging.'], code:'def factorial(n):\n    if n <= 1:\n        return 1\n    return n * factorial(n - 1)\n\nprint(factorial(5))', output:'120', lines:[['if n <= 1','Base case stops recursion.'],['n * factorial(n - 1)','Reduces the problem to n - 1.']], mistakes:['Missing the base case.','Recursive calls that do not reduce the problem.','Ignoring recursion depth for large inputs.'], use:'Use recursion for trees, backtracking, divide-and-conquer, and naturally recursive definitions.', qa:[['What are the two essential parts?', 'A base case and a recursive case that progresses toward it.']], practice:'Compute the sum of 1..n recursively.', hint:'sum(n) = n + sum(n-1).', solution:'def total(n):\n    if n == 0: return 0\n    return n + total(n - 1)', related:['recursion-math-01','recursion-math-02']
  },
  {
    id:'backtracking', level:3, title:'Backtracking', difficulty:'hard', summary:'Explore choices, undo them, and continue searching other possibilities.', what:'Backtracking builds a candidate step by step and abandons a branch when it cannot lead to a valid answer.', why:'It solves permutations, combinations, subsets, Sudoku-like constraints, and many search problems.', simple:'Try a choice, walk forward, and if it fails, step back and try the next choice.', tech:'Backtracking is depth-first search over a decision tree with state restoration after each branch.', steps:['Choose a candidate.','Apply the choice to the current state.','Recurse to the next position.','Undo the choice before exploring the next candidate.'], code:'def subsets(values):\n    answer = []\n    path = []\n    def dfs(i):\n        if i == len(values):\n            answer.append(path.copy())\n            return\n        dfs(i + 1)\n        path.append(values[i])\n        dfs(i + 1)\n        path.pop()\n    dfs(0)\n    return answer\n\nprint(subsets([1, 2]))', output:'[[], [2], [1], [1, 2]]', lines:[['path.append(values[i])','Makes the include choice.'],['dfs(i + 1)','Explores the resulting branch.'],['path.pop()','Undoes the choice before returning.']], mistakes:['Forgetting to undo mutable state.','Appending the same list object instead of a copy.'], use:'Use when the search space is combinatorial and constraints can prune branches.', qa:[['Why is path.pop() necessary?', 'It restores the state so the next branch starts from the same decision point.']], practice:'Generate all permutations of a list.', hint:'Choose one unused value at each depth.', solution:'def permute(values):\n    out = []\n    path = []\n    used = [False] * len(values)\n    # choose, recurse, undo\n    return out', related:['recursion-math-08']
  },

  {
    id:'trees', level:4, title:'Trees', difficulty:'medium', summary:'Learn tree structure, major tree types, traversals, height, balance and the techniques built on them.', what:'A tree is a connected acyclic hierarchy. In practice you will meet general trees, binary trees, full binary trees, complete binary trees, perfect trees, balanced trees, skewed trees and ordered trees such as BSTs.', why:'Trees model folders, DOM structures, syntax trees, organization charts, heaps and many interview problems. Knowing only the definition is not enough; you need to recognise the shape and choose the right traversal or invariant.', simple:'Start with a root. Every child begins another smaller tree. Binary trees limit each node to two children, BSTs add ordering, and balanced trees control height.', tech:'Important distinctions: a full binary tree has 0 or 2 children per node; a complete tree fills levels left-to-right; a perfect tree has every internal node with two children and all leaves at the same depth; a balanced tree keeps height controlled; a skewed tree behaves like a chain. Traversals include preorder, inorder, postorder and level order.', steps:['Learn the node/child representation.','Recognise the tree type from its structural rule.','Master preorder, inorder, postorder and level-order traversal.','Learn height, leaf count, diameter and balance as recursive patterns.','Move to BST operations, then balanced-tree rotations and serialization.'], code:'class Node:\n    def __init__(self, value):\n        self.value = value\n        self.children = []\n\nroot = Node("A")\nroot.children = [Node("B"), Node("C")]\nfor child in root.children:\n    print(child.value)', output:'B\nC', lines:[['self.children = []','Stores child references.'],['root.children = [...]','Connects the root to its children.']], mistakes:['Assuming every tree is binary.','Forgetting that traversal order matters.'], use:'Use trees for hierarchical relationships and recursive divide-into-children problems.', qa:[['What is the difference between a tree and a graph?', 'A tree is connected and acyclic; a general graph may have cycles and disconnected components.']], practice:'Compute the maximum depth of a binary tree.', hint:'Depth is 1 + max(left depth, right depth).', solution:'def depth(node):\n    if not node: return 0\n    return 1 + max(depth(node.left), depth(node.right))', related:[], deepPrograms:['tree-01-binary-tree','tree-02-preorder','tree-03-inorder','tree-04-postorder','tree-05-level-order','tree-06-height','tree-07-leaf-count','tree-08-diameter','tree-09-balanced','tree-10-bst-search','tree-11-bst-insert','tree-12-bst-delete','tree-13-avl-rotation','tree-14-serialize','tree-15-full-check','tree-16-perfect-check','tree-17-complete-check','tree-18-skewed-check']
  },
  {
    id:'binary-search-tree', level:4, title:'Binary Search Tree', difficulty:'medium', summary:'Use ordered binary-tree structure to support search by comparisons.', what:'A BST stores values so values smaller than a node go left and larger values go right.', why:'The ordering property makes search, insertion, and deletion efficient when the tree stays reasonably balanced.', simple:'At each node, decide left or right just like binary search on a tree.', tech:'For a balanced BST, search/insert/delete are O(log n) average; in a degenerate chain they become O(n).', steps:['Compare the target with the current node.','Go left for smaller values.','Go right for larger values.','Stop when found or when the next child is missing.'], code:'def contains(node, target):\n    while node:\n        if node.value == target:\n            return True\n        node = node.left if target < node.value else node.right\n    return False', output:'Boolean result', lines:[['node.left if target < node.value else node.right','Uses the BST ordering property to discard half of the local choices.']], mistakes:['Using the rule on a tree that is not actually a BST.','Ignoring the possibility of an unbalanced tree.'], use:'Use BSTs when ordered dynamic data is needed and balancing guarantees are available.', qa:[['What is inorder traversal of a BST?', 'It visits values in sorted order.']], practice:'Insert a value into a BST.', hint:'Follow the same left/right comparison rule until a missing child is found.', solution:'def insert(node, value):\n    if not node: return Node(value)\n    if value < node.value: node.left = insert(node.left, value)\n    else: node.right = insert(node.right, value)\n    return node', related:[], deepPrograms:['tree-10-bst-search','tree-11-bst-insert','tree-12-bst-delete','tree-13-avl-rotation']
  },
  {
    id:'heap-priority-queue', level:4, title:'Heap / Priority Queue', difficulty:'medium', summary:'Always retrieve the smallest or largest priority efficiently.', what:'A heap is a complete binary-tree structure that keeps the minimum or maximum element at the root.', why:'Priority queues power scheduling, top-k problems, Dijkstra-like algorithms, and streaming problems.', simple:'Imagine a line where the most important person is always moved to the front.', tech:'A binary heap supports O(log n) insertion/removal of the root and O(1) access to the root.', steps:['Define the priority.','Push items into the heap.','Pop the highest-priority item when needed.','For Python min-heaps, store tuples when you need custom priority.'], code:'import heapq\n\nh = []\nheapq.heappush(h, (2, "normal"))\nheapq.heappush(h, (1, "urgent"))\nprint(heapq.heappop(h))', output:"(1, 'urgent')", lines:[['heappush(h, (priority, item))','Adds an item while preserving heap order.'],['heappop(h)','Removes the smallest priority tuple.']], mistakes:['Forgetting Python heapq is a min-heap.','Using the wrong tuple fields for tie-breaking.'], use:'Use a priority queue when the next item is chosen by priority rather than arrival order.', qa:[['Heap vs sorted list?', 'A heap efficiently exposes the best item without fully sorting all items.']], practice:'Find the k smallest values.', hint:'Push values into a heap or maintain a size-k heap.', solution:'import heapq\nsmallest = heapq.nsmallest(k, values)', related:[]
  },
  {
    id:'graphs', level:4, title:'Graphs', difficulty:'medium', summary:'Learn graph types, representations, traversal, connectivity, cycles and the techniques that lead into shortest paths and MSTs.', what:'A graph contains vertices connected by edges. You must distinguish directed vs undirected, weighted vs unweighted, connected vs disconnected, cyclic vs acyclic, and sparse vs dense graphs.', why:'Networks, maps, dependencies, social connections and real systems are graphs. The important skill is not just drawing a graph; it is choosing the representation and algorithm that match the constraints.', simple:'Cities are nodes and roads are edges. Roads may be one-way or two-way, free or costly, and there may be many routes or cycles.', tech:'Common representations are adjacency lists and matrices. Core techniques include BFS, DFS, connected components, cycle detection, bipartite checking and topological sorting. Advanced algorithms include Dijkstra, Bellman-Ford, Floyd-Warshall, DSU, Kruskal, Prim and SCC algorithms.', steps:['Identify graph type and edge meaning.','Choose adjacency list or matrix.','Master BFS and DFS with visited state.','Learn components, cycle detection and bipartite checks.','Then learn topological order, shortest paths, MST and strongly connected components.'], code:'from collections import deque\ngraph = {\n    "A": ["B", "C"],\n    "B": ["D"],\n    "C": ["D"],\n    "D": []\n}\n\nq = deque(["A"])\nseen = {"A"}\nwhile q:\n    node = q.popleft()\n    print(node)\n    for nxt in graph[node]:\n        if nxt not in seen:\n            seen.add(nxt)\n            q.append(nxt)', output:'A\nB\nC\nD', lines:[['seen = {"A"}','Prevents revisiting nodes.'],['for nxt in graph[node]','Explores outgoing edges.'],['q.append(nxt)','Schedules the neighbor for BFS.']], mistakes:['Forgetting visited tracking in cyclic graphs.','Mixing up directed and undirected representations.'], use:'Use graphs whenever relationships are many-to-many or cycles are possible.', qa:[['BFS vs DFS?', 'BFS explores by distance/layers; DFS explores one branch deeply before backtracking.']], practice:'Count connected components in an undirected graph.', hint:'Run DFS/BFS from every unvisited node.', solution:'seen = set()\ncomponents = 0\nfor node in graph:\n    if node not in seen:\n        components += 1\n        # DFS/BFS from node', related:[], deepPrograms:['graph-01-adjacency-list','graph-02-adjacency-matrix','graph-03-bfs','graph-04-dfs','graph-05-components','graph-06-cycle-undirected','graph-07-cycle-directed','graph-08-bipartite','graph-09-topological','graph-10-unweighted-shortest','graph-11-dijkstra','graph-12-bellman-ford','graph-13-floyd-warshall','graph-14-dsu','graph-15-kruskal','graph-16-prims','graph-17-scc','graph-18-directed-vs-undirected','graph-19-weighted-vs-unweighted']
  },
  {
    id:'trie', level:4, title:'Trie', difficulty:'hard', summary:'Store strings by shared prefixes for fast prefix queries.', what:'A trie is a tree where each edge represents a character and a path represents a prefix.', why:'It is useful for autocomplete, prefix search, dictionaries, and word lookup.', simple:'Words share the same starting hallway: cat and car both walk through c → a before splitting.', tech:'Trie insertion and exact/prefix lookup take O(L), where L is the string length, independent of the number of stored words aside from branching/memory costs.', steps:['Start at the root.','For each character, follow or create its child.','Mark the end of a complete word.','For prefix queries, stop after the prefix characters.'], code:'class TrieNode:\n    def __init__(self):\n        self.children = {}\n        self.end = False\n\nroot = TrieNode()\nword = "cat"\nnode = root\nfor ch in word:\n    node = node.children.setdefault(ch, TrieNode())\nnode.end = True', output:'Trie containing "cat"', lines:[['children.setdefault(ch, TrieNode())','Gets an existing child or creates one.'],['node.end = True','Marks that a complete word ends here.']], mistakes:['Confusing a prefix with a complete word.','Using a trie when ordinary hashing is enough and memory is more important.'], use:'Use tries for prefix-heavy workloads such as autocomplete and dictionary prefix search.', qa:[['What is the lookup complexity?', 'O(L) for a word/prefix of length L.']], practice:'Implement starts_with(prefix).', hint:'Walk the trie for each prefix character and return whether every edge exists.', solution:'def starts_with(root, prefix):\n    node = root\n    for ch in prefix:\n        if ch not in node.children: return False\n        node = node.children[ch]\n    return True', related:[]
  },

  {
    id:'greedy', level:5, title:'Greedy Algorithms', difficulty:'medium', summary:'Make the best local choice when the problem guarantees that local choices can lead to a global optimum.', what:'A greedy algorithm commits to the best-looking choice at each step without revisiting earlier decisions.', why:'When a greedy-choice property holds, it can be simpler and faster than dynamic programming.', simple:'Always take the best next step—but only when you can prove that doing so cannot hurt the final answer.', tech:'Greedy correctness usually relies on an exchange argument or a structural property showing that an optimal solution can include the locally optimal choice.', steps:['Define the local choice.','Ask whether an optimal solution can always be transformed to include it.','Make the choice and reduce the problem.','Prove correctness before trusting the heuristic.'], code:'coins = [25, 10, 5, 1]\namount = 63\nused = []\nfor coin in coins:\n    while amount >= coin:\n        amount -= coin\n        used.append(coin)\nprint(used)', output:'[25, 25, 10, 1, 1, 1]', lines:[['for coin in coins','Considers larger denominations first.'],['while amount >= coin','Takes the coin whenever it is safe for this coin system.']], mistakes:['Assuming every optimization problem is greedy.','Using coin-change greedy for arbitrary denominations where it may fail.'], use:'Use greedy only after proving the greedy-choice property for the problem.', qa:[['Why can greedy fail?', 'A locally best choice can block a globally optimal combination.']], practice:'Schedule the maximum number of non-overlapping intervals.', hint:'Sort by finishing time and always take the earliest finishing compatible interval.', solution:'intervals.sort(key=lambda x: x[1])\nend = -float("inf")\ncount = 0\nfor start, finish in intervals:\n    if start >= end:\n        count += 1\n        end = finish', related:[]
  },
  {
    id:'divide-and-conquer', level:5, title:'Divide & Conquer', difficulty:'medium', summary:'Split a problem into smaller independent pieces, solve them, and combine the results.', what:'Divide-and-conquer repeatedly partitions a problem until the pieces are easy, then combines their answers.', why:'It produces efficient algorithms such as merge sort and supports parallel-style reasoning.', simple:'Cut a big job into smaller jobs, solve each, then assemble the result.', tech:'If T(n)=aT(n/b)+f(n), recurrence analysis describes the resulting complexity. Merge sort gives O(n log n).', steps:['Divide the input.','Recursively solve each part.','Combine the partial results.','Check the recurrence or total work.'], code:'def merge_sort(values):\n    if len(values) <= 1:\n        return values\n    mid = len(values) // 2\n    left = merge_sort(values[:mid])\n    right = merge_sort(values[mid:])\n    return merge(left, right)\n\ndef merge(a, b):\n    out = []\n    i = j = 0\n    while i < len(a) and j < len(b):\n        if a[i] <= b[j]:\n            out.append(a[i]); i += 1\n        else:\n            out.append(b[j]); j += 1\n    return out + a[i:] + b[j:]', output:'Sorted list', lines:[['mid = len(values) // 2','Splits the input into two halves.'],['merge(left, right)','Combines two sorted halves.']], mistakes:['Forgetting a base case.','Ignoring the cost of the combine step.'], use:'Use divide-and-conquer when subproblems are independent and a clean combine step exists.', qa:[['Why is merge sort O(n log n)?', 'There are log n levels of splitting and O(n) merging work at each level.']], practice:'Find the maximum value using divide and conquer.', hint:'Split, find each half maximum, then take max.', solution:'def maximum(a):\n    if len(a) == 1: return a[0]\n    mid = len(a)//2\n    return max(maximum(a[:mid]), maximum(a[mid:]))', related:['searching-sorting-09']
  },
  {
    id:'dynamic-programming', level:5, title:'Dynamic Programming', difficulty:'hard', summary:'Reuse overlapping subproblem answers instead of recomputing them.', what:'Dynamic programming stores results of repeated subproblems and builds an optimal answer from smaller states.', why:'It turns many exponential recursive solutions into polynomial-time algorithms.', simple:'If you keep solving the same small question, write its answer down and reuse it.', tech:'DP requires a state definition, transition, base cases, and an evaluation order or memoization strategy. It commonly exploits overlapping subproblems and optimal substructure.', steps:['Define what a state means.','Write the transition from smaller states.','Set base cases.','Choose memoization or bottom-up tabulation.','Estimate states × transition cost.'], code:'def fib(n):\n    if n <= 1:\n        return n\n    dp = [0, 1]\n    for i in range(2, n + 1):\n        dp.append(dp[-1] + dp[-2])\n    return dp[n]\n\nprint(fib(10))', output:'55', lines:[['dp = [0, 1]','Stores the first two states.'],['dp.append(dp[-1] + dp[-2])','Builds the next state from previous states.']], mistakes:['Defining a state that does not contain enough information.','Using DP when subproblems do not overlap.','Mixing indexing conventions.'], use:'Use DP when recursive choices revisit the same states and the answer can be expressed from smaller states.', qa:[['Memoization vs tabulation?', 'Memoization is top-down caching of recursive states; tabulation is bottom-up computation of states in order.']], practice:'Solve climbing stairs where you can climb 1 or 2 steps.', hint:'dp[i] = dp[i-1] + dp[i-2].', solution:'dp = [1, 1]\nfor i in range(2, n + 1):\n    dp.append(dp[-1] + dp[-2])\nanswer = dp[n]', related:['dynamic-programming-01','dynamic-programming-02']
  },
  {
    id:'bit-manipulation', level:5, title:'Bit Manipulation', difficulty:'medium', summary:'Use binary representation and bitwise operations to solve compact low-level problems.', what:'Bit manipulation works directly with the binary bits of integers using &, |, ^, ~, <<, and >>.', why:'It appears in masks, parity checks, subsets, permissions, XOR tricks, and performance-sensitive algorithms.', simple:'Instead of treating a number as a whole, inspect or change its individual 0/1 switches.', tech:'Bitwise operators act on integer bit representations. Masks isolate positions; XOR toggles bits and cancels equal values.', steps:['Write the number in binary.','Choose a mask for the target bit(s).','Apply the operator.','Convert back or interpret the resulting bits.'], code:'n = 10          # 1010\nmask = 1 << 2    # 0100\nprint(n ^ mask)  # toggle bit 2', output:'14', lines:[['1 << 2','Creates a mask with bit 2 set.'],['n ^ mask','XOR toggles the selected bit.']], mistakes:['Confusing bit positions starting at 0 with positions starting at 1.','Using XOR tricks without checking the input constraints.'], use:'Use bit manipulation for masks, parity, powers of two, XOR uniqueness, and compact state representation.', qa:[['What does x ^ x equal?', '0. XOR cancels equal bits.'],['What does x ^ 0 equal?', 'x.']], practice:'Check whether n is a power of two.', hint:'A positive power of two has exactly one set bit.', solution:'answer = n > 0 and (n & (n - 1)) == 0', related:['bit-manipulation-01','bit-manipulation-06']
  },
  {
    id:'graph-algorithms', level:5, title:'Graph Algorithms', difficulty:'hard', summary:'Go from graph traversal to shortest paths, ordering, and connectivity.', what:'Graph algorithms solve path, reachability, dependency, connectivity, and optimization problems on networks.', why:'Once graphs are understood, many real-world problems become recognizable as BFS, DFS, shortest-path, or topological-order tasks.', simple:'A map gives you roads; the algorithm decides whether you need to explore, find the cheapest route, or respect dependencies.', tech:'Common families include BFS/DFS, Dijkstra for non-negative weighted shortest paths, Bellman-Ford for negative edges, and topological sorting for DAG dependencies.', steps:['Identify the graph model and edge weights.','Choose the algorithm based on constraints.','Maintain visited, distance, or indegree state as required.','Prove that the algorithm’s assumptions match the input.'], code:'import heapq\n\ndef dijkstra(graph, start):\n    dist = {node: float("inf") for node in graph}\n    dist[start] = 0\n    heap = [(0, start)]\n    while heap:\n        d, node = heapq.heappop(heap)\n        if d != dist[node]:\n            continue\n        for nxt, weight in graph[node]:\n            nd = d + weight\n            if nd < dist[nxt]:\n                dist[nxt] = nd\n                heapq.heappush(heap, (nd, nxt))\n    return dist', output:'Shortest distance map', lines:[['dist[start] = 0','The source has distance zero.'],['nd = d + weight','Builds a candidate distance through the current edge.'],['if nd < dist[nxt]','Relaxes the neighbor when a shorter route is found.']], mistakes:['Using Dijkstra with negative edge weights.','Forgetting visited/stale-entry handling.'], use:'Use graph algorithms when the input is a network of relationships and the question asks about reachability, paths, costs, or dependencies.', qa:[['When should BFS find shortest paths?', 'In an unweighted graph, BFS finds shortest paths measured by number of edges.'],['When is Dijkstra appropriate?', 'For shortest paths with non-negative edge weights.']], practice:'Topologically sort tasks with prerequisites.', hint:'Use indegrees and a queue of zero-indegree nodes.', solution:'from collections import deque\nq = deque([n for n in graph if indegree[n] == 0])\norder = []\nwhile q:\n    node = q.popleft()\n    order.append(node)\n    for nxt in graph[node]:\n        indegree[nxt] -= 1\n        if indegree[nxt] == 0:\n            q.append(nxt)', related:[], deepPrograms:['graph-09-topological','graph-10-unweighted-shortest','graph-11-dijkstra','graph-12-bellman-ford','graph-13-floyd-warshall','graph-14-dsu','graph-15-kruskal','graph-16-prims','graph-17-scc','graph-18-directed-vs-undirected','graph-19-weighted-vs-unweighted']
  }
];
